'use strict';
let buyerTab='overview',buyerStatus='전체',buyerQuery='',buyerPeriod='all';
function buyerSpace(){db.buyerSpaces??={};return db.buyerSpaces[MarketCore.accountId(db)]??={addresses:[],reviews:[]}}
function myOrders(){return db.orders.filter(o=>AccountCore.owns(db,o))}
function myClaims(){const ids=new Set(myOrders().map(o=>o.id));return db.market.claims.filter(c=>ids.has(c.orderId))}
function myInquiries(){return db.market.inquiries.filter(q=>q.ownerAccount===MarketCore.accountId(db))}
function buyerCoupons(){return db.market.coupons.filter(c=>c.active&&c.expires>=new Date().toISOString().slice(0,10)&&c.used<c.limit&&(!c.org||!db.buyerOrg||c.org===db.buyerOrg))}
function promoSection(){return `<section class="section promo-section"><p class="section-overline">A LITTLE GOOD, A BIG SMILE</p><div class="section-heading"><h2>42초로 만나는 방긋마켓</h2><span class="small muted">BRAND FILM</span></div><video id="brand-film" controls playsinline preload="none" poster="/assets/video/banggeut-story-poster.jpg" aria-label="방긋마켓 홍보 영상 42초"><source src="/assets/video/banggeut-story.mp4" type="video/mp4">동영상을 재생할 수 없습니다.</video><p>사는 마음도, 나누는 마음도 방긋.<br>좋은 물건이 이어 주는 따뜻한 이야기를 만나 보세요.</p><a href="#/institutions" class="text-link">나에게 맞는 기관몰 만나기 ${icon('arrow')}</a></section>`}
const buyerTabs=[['overview','나의 쇼핑'],['orders','주문·배송'],['claims','취소·교환·반품'],['coupons','쿠폰·혜택'],['wishes','찜한 상품'],['stores','관심 기관몰'],['inquiries','내 문의'],['reviews','구매 후기'],['addresses','배송지 관리']];
const buyerGo=(t,label,cls='pill-btn')=>btn('buyer-tab',label,cls,`data-tab="${t}"`);
function buyerPage(){const orders=myOrders();return header()+`<section class="buyer-hero"><span class="section-overline">MY BANGGEUT</span><div class="buyer-greeting">${ownProfileImage('large')}<div><h1>${esc(db.profile.name)}님, 방긋!</h1><p>기분 좋은 쇼핑의 모든 순간을 한곳에.</p></div><a href="#/profile" class="icon-btn" aria-label="프로필 설정">${icon('settings')}</a></div>${db.buyerOrg?`<a class="buyer-membership" href="#/institution/${db.buyerOrg}"><img src="${institutionLogo(db.buyerOrg)}" alt="기관 로고"><span><small>나의 기관 쇼핑몰</small><b>${esc(mallTitle(db.buyerOrg))}</b></span>${icon('chevron')}</a>`:''}<div class="buyer-summary">${[['orders','box','구매 내역',orders.length],['coupons','gift','사용 가능 쿠폰',buyerCoupons().length],['wishes','heart','찜한 상품',db.wishes.length]].map(([t,i,l,n])=>buyerGo(t,icon(i)+`<strong>${n}</strong><span>${l}</span>`,'')).join('')}</div></section><nav class="buyer-tabs" aria-label="마이페이지 메뉴">${buyerTabs.map(([k,l])=>btn('buyer-tab',l,buyerTab===k?'active':'',`data-tab="${k}" ${buyerTab===k?'aria-current="page"':''}`)).join('')}</nav><section class="section buyer-body" id="buyer-content">${buyerContent(orders,buyerSpace())}</section><section class="buyer-help"><a href="#/profile">${icon('user')} 내 정보·프로필 관리 ${icon('chevron')}</a><a href="#/cart">${icon('cart')} 장바구니 ${icon('chevron')}</a>${btn('buyer-help',icon('info')+' 쇼핑 이용 안내 '+icon('chevron'),'')}${btn('logout',icon('logout')+' 로그아웃','')}</section>`+bottomNav()}
function buyerContent(orders,space){
 if(buyerTab==='overview')return `<div class="section-heading"><h2>주문은 어디쯤 왔을까요?</h2>${buyerGo('orders','전체 보기','text-link')}</div><div class="buyer-progress">${['신규 주문','상품 준비 중','배송 중','배송 완료','구매 확정'].map((s,i)=>btn('buyer-order-state',`<strong>${orders.reduce((n,o)=>n+o.fulfillments.filter(f=>f.status===s).length,0)}</strong><span>${['주문 접수','상품 준비','배송 중','배송 완료','구매 확정'][i]}</span>`,'',`data-status="${s}"`)).join('')}</div><p class="small muted">기관별 배송 건수를 기준으로 표시합니다.</p><div class="buyer-action-grid">${[['claims','취소·교환·반품',myClaims().filter(c=>!['처리 완료','접수 철회'].includes(c.status)).length+'건 진행'],['inquiries','나의 문의',myInquiries().filter(q=>q.status==='답변 완료').length+'건 답변'],['addresses','배송지 관리',space.addresses.length+'곳 저장'],['reviews','구매 후기','소중한 경험 남기기']].map(([t,l,s])=>buyerGo(t,`<strong>${l}</strong><small>${s}</small>${icon('chevron')}`,'')).join('')}</div><div class="section-heading mt-20"><h2>최근 구매 목록</h2></div>${buyerOrderList(orders.slice(0,3))}<p class="buyer-demo">체험 계정의 주문 내역입니다. 실제 결제·배송·환불은 연결 전입니다.</p>`;
 if(buyerTab==='orders'){const rows=orders.filter(o=>(buyerStatus==='전체'||o.fulfillments.some(f=>f.status===buyerStatus))&&(!buyerQuery||[o.id,...o.items.map(i=>i.name)].join(' ').toLowerCase().includes(buyerQuery.toLowerCase()))&&(buyerPeriod==='all'||Date.parse(o.createdAt)>=Date.now()-Number(buyerPeriod)*86400000));return `<div class="section-heading"><h2>주문·배송 조회</h2><span class="small muted">${rows.length}건</span></div><form id="buyer-order-search" class="buyer-search"><input name="query" value="${esc(buyerQuery)}" placeholder="상품명 또는 주문번호" aria-label="주문 검색"><select name="period" aria-label="주문 기간">${[['all','전체 기간'],['30','최근 1개월'],['90','최근 3개월'],['365','최근 1년']].map(([v,l])=>`<option value="${v}" ${buyerPeriod===v?'selected':''}>${l}</option>`).join('')}</select><button class="primary-btn green">검색</button></form><div class="chips">${['전체','신규 주문','상품 준비 중','배송 중','배송 완료','구매 확정','취소 완료','반품 완료'].map(s=>btn('buyer-order-state',s,'chip '+(buyerStatus===s?'active':''),`data-status="${s}"`)).join('')}</div>${buyerOrderList(rows)}<p class="small muted">주문 상세에서 운송장과 배송지, 결제 금액, 취소·교환·반품 신청을 확인하세요.</p>`}
 if(buyerTab==='claims')return `<div class="section-heading"><h2>취소·교환·반품 내역</h2></div>${myClaims().map(c=>`<article class="report-card"><div class="split-row"><h3>${esc(c.type)} 요청</h3>${status(c.status)}</div><p class="small">${esc(c.orderId)} · ${esc(org(c.org).name)}</p><p>${esc(c.reason)}</p>${btn('order-detail','관련 주문 확인','pill-btn',`data-id="${c.orderId}"`)}</article>`).join('')||empty('접수한 요청이 없어요','주문 상세에서 주문 상태에 따라 요청할 수 있어요.',buyerGo('orders','주문 확인하기'))}`;
 if(buyerTab==='coupons')return `<div class="section-heading"><h2>사용 가능한 쇼핑 혜택</h2></div>${buyerCoupons().map(c=>`<article class="report-card buyer-coupon"><strong>${c.type==='percent'?c.amount+'%':won(c.amount)} 할인</strong><h3>${esc(c.name)}</h3><p>${c.org?esc(mallTitle(c.org)):'전체 기관몰'} · ${esc(c.code)}</p><p class="small muted">${won(c.min)} 이상 구매 · 최대 ${c.max?won(c.max):'제한 없음'}<br>${esc(c.expires)}까지</p><a class="pill-btn" href="${c.org?'#/institution/'+c.org:'#/shop'}">상품 보러 가기</a></article>`).join('')||empty('현재 사용 가능한 쿠폰이 없어요','기관몰에서 제공하는 혜택을 기다려 주세요.')}<p class="small muted">주문서의 쿠폰 선택에서 적용할 수 있어요. 적용 조건과 남은 사용 수량은 주문 시 다시 확인됩니다.</p>`;
 if(buyerTab==='wishes')return `<div class="section-heading"><h2>마음에 담은 상품</h2></div><div class="product-grid">${db.wishes.map(product).filter(p=>p&&MarketCore.publicProduct(db,p)).map(productCard).join('')||empty('찜한 상품이 없어요','상품의 하트를 눌러 담아 보세요.','<a href="#/shop" class="secondary-btn">상품 둘러보기</a>')}</div>`;
 if(buyerTab==='stores')return `<div class="section-heading"><h2>응원하는 기관 쇼핑몰</h2></div><div class="org-grid">${db.follows.map(id=>db.orgs.find(o=>o.id===id)).filter(Boolean).map(orgCard).join('')||empty('관심 기관몰을 만나 보세요','기관몰에서 응원하기를 눌러 저장할 수 있어요.','<a href="#/institutions" class="secondary-btn">기관몰 둘러보기</a>')}</div>`;
 if(buyerTab==='inquiries')return `<div class="section-heading"><h2>내 문의와 답변</h2></div>${myInquiries().map(q=>`<article class="report-card"><div class="split-row"><h3>${esc(q.title)}</h3>${status(q.status)}</div><p class="small muted">${esc(org(q.org).name)} · ${esc(q.date)}</p><p>${esc(q.body)}</p>${q.answer?`<div class="buyer-answer"><b>기관의 답변</b><p>${esc(q.answer)}</p></div>`:'<p class="small muted">기관의 답변을 기다리고 있어요.</p>'}${q.productId?`<a href="#/product/${q.productId}" class="text-link">문의 상품 보기</a>`:''}</article>`).join('')||empty('등록한 문의가 없어요','상품 상세의 문의하기에서 궁금한 점을 남겨 주세요.','<a href="#/shop" class="secondary-btn">상품 둘러보기</a>')}`;
 if(buyerTab==='reviews'){const eligible=orders.flatMap(o=>o.items.filter(i=>reviewAllowed(o,i)).map(i=>({o,i})));return `<div class="section-heading"><h2>나의 구매 후기</h2></div>${eligible.map(({o,i})=>{const r=space.reviews.find(r=>r.order===o.id&&r.product===i.id);return `<article class="report-card"><h3>${esc(i.name)}</h3><p class="small muted">${esc(o.id)}</p>${r?`<p class="buyer-stars">${'★'.repeat(r.rating)}${'☆'.repeat(5-r.rating)}</p><p>${esc(r.body)}</p>`:''}${btn('buyer-review',r?'후기 수정':'후기 작성','pill-btn',`data-order="${o.id}" data-product="${i.id}"`)}</article>`}).join('')||empty('배송 완료 후 후기를 남겨 주세요','받아 본 상품의 경험을 기록할 수 있어요.',buyerGo('orders','주문 확인하기'))}<p class="small muted">작성한 후기는 현재 이 브라우저의 내 계정에 보관됩니다.</p>`}
 if(buyerTab==='addresses')return `<div class="section-heading"><h2>배송지 관리</h2>${btn('buyer-address','+ 배송지 추가','pill-btn')}</div>${space.addresses.map(a=>`<article class="report-card"><div class="split-row"><h3>${esc(a.label)}</h3>${a.default?status('기본 배송지'):''}</div><p>${esc(a.name)} · ${esc(a.phone)}</p><p>${esc(a.address)}</p><p class="small muted">${esc(a.memo)}</p><div class="button-group">${btn('buyer-address','수정','pill-btn',`data-id="${a.id}"`)}${!a.default?btn('buyer-address-default','기본으로','pill-btn',`data-id="${a.id}"`):''}${btn('buyer-address-delete','삭제','pill-btn',`data-id="${a.id}"`)}</div></article>`).join('')||empty('저장된 배송지가 없어요','자주 쓰는 배송지를 등록하고 주문서에 불러오세요.')}<p class="buyer-demo">체험용 주소만 입력해 주세요. 기본 배송지는 다음 주문서에 자동으로 채워집니다.</p>`;
 return '';
}
function reviewAllowed(o,i){return o&&i&&o.fulfillments.some(f=>f.org===i.org&&['배송 완료','구매 확정'].includes(f.status))}
function fillCheckoutAddress(a){const f=document.getElementById('merchant-checkout-form');if(f)for(const k of ['name','phone','address','memo'])f.elements[k].value=a[k]||''}
function initBuyer(){
 const oldMy=myPage;myPage=()=>db.role==='buyer'?buyerPage():oldMy();
 const oldHome=home;home=()=>{const html=oldHome(),marker='<section class="section"><div class="section-heading"><div><p class="section-overline">STORES WITH A PURPOSE';return html.includes(marker)?html.replace(marker,promoSection()+marker):html.replace('<footer',promoSection()+'<footer')};
 const oldCart=cartPage;cartPage=function(checkout){const html=oldCart(checkout);return checkout&&db.role==='buyer'?html.replace('<h3>수령인과 배송지</h3>',`<h3>수령인과 배송지</h3><label class="field">저장한 배송지<select id="buyer-checkout-address"><option value="">직접 입력</option>${buyerSpace().addresses.map(a=>`<option value="${a.id}" ${a.default?'selected':''}>${esc(a.label)}${a.default?' · 기본':''}</option>`).join('')}</select></label>`):html};
 const oldRender=render;render=function(reset){oldRender(reset);if(db.role==='buyer'&&currentRoute==='/checkout'){const a=buyerSpace().addresses.find(a=>a.default);if(a)fillCheckoutAddress(a)}};
 const oldLogin=actions['test-login'];actions['test-login']=el=>{buyerTab='overview';buyerStatus='전체';buyerQuery='';buyerPeriod='all';oldLogin(el)};
 Object.assign(actions,{
 'buyer-tab':el=>{buyerTab=el.dataset.tab;render();$('#buyer-content')?.scrollIntoView({block:'start'})},
 'buyer-order-state':el=>{buyerTab='orders';buyerStatus=el.dataset.status;render();$('#buyer-content')?.scrollIntoView({block:'start'})},
 'buyer-help':()=>openModal('쇼핑 이용 안내',`<div class="report-card"><h3>주문·배송</h3><p>주문 상세에서 기관별 준비 상태와 운송장을 확인하세요. 상품은 각 기관의 배송 정책에 따라 준비됩니다.</p><h3>취소·교환·반품</h3><p>주문 접수·준비 중에는 취소를, 배송 단계에는 교환·반품을 요청할 수 있어요. 기관이 확인 후 처리하며 비용과 처리 가능 여부는 기관 정책을 따릅니다.</p><h3>쿠폰·문의</h3><p>쿠폰은 주문서에서 선택하세요. 상품 문의는 상품 상세에서 남기고 내 문의에서 답변을 확인할 수 있어요.</p></div>`),
 'buyer-address':el=>{if(db.role!=='buyer')return;const a=buyerSpace().addresses.find(a=>a.id===el.dataset.id)||{};openModal(a.id?'배송지 수정':'배송지 추가',`<form id="buyer-address-form" data-id="${a.id||''}">${field('배송지 이름','label',a.label||'','text','required maxlength="30"')}${field('받는 분','name',a.name||'','text','required maxlength="40"')}${field('연락처 · 체험 번호','phone',a.phone||'','text','required maxlength="30"')}${field('배송지 · 체험 주소','address',a.address||'','text','required maxlength="200"')}${field('배송 요청사항','memo',a.memo||'','text','maxlength="200"')}<label class="check-line"><input type="checkbox" name="default" ${a.default?'checked':''}>기본 배송지로 설정</label><p class="small muted">체험용 정보만 입력해 주세요.</p><button class="primary-btn green full">배송지 저장</button></form>`)},
 'buyer-address-default':el=>{if(db.role!=='buyer')return;const list=buyerSpace().addresses;if(!list.some(a=>a.id===el.dataset.id))return;list.forEach(a=>a.default=a.id===el.dataset.id);save();render()},
 'buyer-address-delete':el=>{if(db.role!=='buyer')return;const s=buyerSpace();s.addresses=s.addresses.filter(a=>a.id!==el.dataset.id);if(s.addresses.length&&!s.addresses.some(a=>a.default))s.addresses[0].default=true;save();render();toast('배송지를 삭제했습니다.')},
 'buyer-review':el=>{if(db.role!=='buyer')return;const o=myOrders().find(o=>o.id===el.dataset.order),i=o?.items.find(i=>i.id===el.dataset.product);if(!reviewAllowed(o,i))return;const r=buyerSpace().reviews.find(r=>r.order===o.id&&r.product===i.id)||{};openModal('구매 후기',`<form id="buyer-review-form" data-order="${o.id}" data-product="${i.id}"><h3>${esc(i.name)}</h3>${selectField('별점','rating',[['5','★★★★★ 아주 좋아요'],['4','★★★★ 좋아요'],['3','★★★ 보통이에요'],['2','★★ 아쉬워요'],['1','★ 많이 아쉬워요']],String(r.rating||5))}<label class="field">구매 후기<textarea name="body" required minlength="5" maxlength="1000">${esc(r.body||'')}</textarea></label><button class="primary-btn green full">후기 저장</button></form>`)}
 });
 document.addEventListener('submit',e=>{const f=e.target;if(!f.id?.startsWith('buyer-'))return;e.preventDefault();if(db.role!=='buyer')return;const v=Object.fromEntries(new FormData(f));
 if(f.id==='buyer-order-search'){buyerQuery=v.query.trim();buyerPeriod=v.period;render();$('#buyer-content')?.scrollIntoView({block:'start'});return}
 if(f.id==='buyer-address-form'){const list=buyerSpace().addresses,old=list.find(a=>a.id===f.dataset.id);if(!v.name.trim()||!v.address.trim()||!v.label.trim()){toast('배송지 정보를 입력해 주세요.');return}const a={id:old?.id||MarketCore.uid('ADR'),label:v.label.trim(),name:v.name.trim(),phone:v.phone.trim(),address:v.address.trim(),memo:v.memo.trim(),default:v.default==='on'||!list.length};if(a.default)list.forEach(x=>x.default=false);if(old)Object.assign(old,a);else list.push(a);if(!list.some(x=>x.default))list[0].default=true;save();closeModal();render();toast('배송지를 저장했습니다.')}
 if(f.id==='buyer-review-form'){const o=myOrders().find(o=>o.id===f.dataset.order),i=o?.items.find(i=>i.id===f.dataset.product);if(!reviewAllowed(o,i))return;const rating=Number(v.rating);if(!Number.isInteger(rating)||rating<1||rating>5||v.body.trim().length<5)return;const list=buyerSpace().reviews,old=list.find(r=>r.order===o.id&&r.product===i.id),r={order:o.id,product:i.id,rating,body:v.body.trim(),date:new Date().toISOString()};if(old)Object.assign(old,r);else list.push(r);save();closeModal();render();toast('후기를 저장했습니다.')}
 });
 document.addEventListener('change',e=>{if(e.target.id==='buyer-checkout-address'&&db.role==='buyer')fillCheckoutAddress(buyerSpace().addresses.find(a=>a.id===e.target.value)||{name:'',phone:'',address:'',memo:''})});
}
